&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-orderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9uojk&quot; data-offset-key=&quot;bq54d-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;bq54d-0-0&quot;&gt;&lt;strong&gt;&lt;span data-offset-key=&quot;bq54d-0-0&quot;&gt;&lt;span data-text=&quot;true&quot;&gt;Core Finance Operations&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-offset-key=&quot;bq54d-0-1&quot;&gt;&lt;span data-text=&quot;true&quot;&gt; — Own month-end and quarter-end close activities including expense accruals, journal entries, variance analysis, and supporting schedules.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;public-DraftStyleDefault-orderedListItem public-DraftStyleDefault-depth0 public-DraftStyleDefault-listLTR&quot; data-block=&quot;true&quot; data-editor=&quot;9uojk&quot; data-offset-key=&quot;6aqt9-0-0&quot;&gt;
